function tests=test_function_prepare_inputs
tests=functiontests(localfunctions);
end
function testDatasetIndependentRoiAndVoxelPreparation(t)
old=path;cleanupPath=onCleanup(@()path(old));root=fileparts(fileparts(mfilename('fullpath')));addpath(root);setup_function('D:/matlab/atoolbox/spm12');folder=tempname;mkdir(folder);cleanup=onCleanup(@()rmdir(folder,'s'));
mask=fullfile(folder,'mask.nii');roi=fullfile(folder,'roi.nii');bold=fullfile(folder,'bold.nii');v=struct('fname',mask,'dim',[3 3 3],'dt',[16 0],'mat',eye(4),'pinfo',[1;0;0],'n',[1 1],'descrip','synthetic');spm_write_vol(v,ones(3,3,3));v.fname=roi;labels=ones(3,3,3);labels(15:end)=2;spm_write_vol(v,labels);
frames=cell(24,1);for k=1:24,v.fname=fullfile(folder,sprintf('frame%d.nii',k));v.n=[1 1];spm_write_vol(v,ones(3,3,3)*sin(k/3)+reshape((1:27)/100,3,3,3));frames{k}=v.fname;end;spm_file_merge(char(frames),bold,0);ni=nifti(bold);ni.timing.tspace=1;create(ni);
tab=table("newperson","visit1","scan1",string(bold),string(mask),string(roi),1,"unfiltered_unregressed",0,"","engineering",'VariableNames',{'subject','session','run','bold','mask','roi_file','tr_seconds','temporal_state','smoothing_fwhm_mm','confounds','purpose'});manifest=fullfile(folder,'runs.tsv');writetable(tab,manifest,'FileType','text','Delimiter','\t');c=prepare_inputs_config;c.manifestFile=manifest;c.outputRoot=fullfile(folder,'roi_out');c.execute=true;r=run_prepare_inputs(c);s=load(fullfile(c.outputRoot,'newperson','visit1','scan1','input.mat'));verifySize(t,s.data.y,[24 2]);verifyEqual(t,s.data.roiNames,["roi_1";"roi_2"]);verifyTrue(t,isfile(r.manifestFile));fc=regularized_fc_config;fc.manifestFile=r.manifestFile;fc.outputRoot=fullfile(folder,'oas_out');fc.execute=true;run_regularized_fc(fc);verifyTrue(t,isfile(fullfile(fc.outputRoot,'newperson','visit1','scan1','regularized_fc.mat')));c.mode='voxels';c.outputRoot=fullfile(folder,'voxel_out');run_prepare_inputs(c);s=load(fullfile(c.outputRoot,'newperson','visit1','scan1','input.mat'));verifySize(t,s.data.y,[24 27]);verifyEqual(t,s.data.frameIndices,(1:24)');verifyTrue(t,isfield(s.data,'space'));
end
function testRefusesRepeatedNuisanceAndPreservesSource(t)
old=path;cleanupPath=onCleanup(@()path(old));addpath(fileparts(fileparts(mfilename('fullpath'))));setup_function;folder=tempname;mkdir(folder);cleanup=onCleanup(@()rmdir(folder,'s'));for f={'bold.nii','mask.nii','roi.nii','confounds.tsv'},fid=fopen(fullfile(folder,f{1}),'w');fwrite(fid,'unchanged');fclose(fid);end
tab=table("p","","r",string(fullfile(folder,'bold.nii')),string(fullfile(folder,'mask.nii')),string(fullfile(folder,'roi.nii')),1,"nuisance_regressed_unfiltered",0,string(fullfile(folder,'confounds.tsv')),"engineering",'VariableNames',{'subject','session','run','bold','mask','roi_file','tr_seconds','temporal_state','smoothing_fwhm_mm','confounds','purpose'});manifest=fullfile(folder,'runs.tsv');writetable(tab,manifest,'FileType','text','Delimiter','\t');c=prepare_inputs_config;c.manifestFile=manifest;c.outputRoot=fullfile(folder,'out');verifyError(t,@()run_prepare_inputs(c),'cog:TemporalState');verifyFalse(t,isfolder(c.outputRoot));verifyEqual(t,fileread(fullfile(folder,'bold.nii')),'unchanged');
end
